template:
use std::sync::atomic::AtomicI32;
use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::thread;

fn main() {
    let counter = Arc::new(AtomicI32::new(5));
    let c = Arc::clone(&counter);
    thread::spawn(move || {
        c.⟦op⟧(1, Ordering::Relaxed);
    }).join().unwrap();
    assert_eq!(counter.⟦ld⟧(Ordering::Relaxed), 6);
}
